usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Projects.Roles.Update(
		context.TODO(),
		"project_id",
		"role_id",
		openai.ProjectRoleUpdateParams{
			Permissions: []string{"string"},
			Description: param.NewOpt[string]("string"),
			RoleName: param.NewOpt[string]("string"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
